// #10/AK1: random tests of the library. Random libraries in memory (invented titles, generated bytes, never
// the real library) get random sequences of sorting, moving, folder and edit operations.
// - Sorting and moving into folders neither lose nor duplicate a track, and every track lies in exactly one
//   existing folder (or none).
// - Saving and loading gives the same state.
// - #114: playlists take part (created, filled, reordered, switched to «only on this device», deleted); they
//   list only tracks of the library, and saving and loading keeps them with their order.
import 'dart:convert';
import 'dart:io';
import 'dart:math';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:woodshed_player/library/library.dart';

import '../fakes.dart';
import 'property.dart';

const words = [
  'Etüde',
  'Tonleiter',
  'Akkorde',
  'Arpeggio',
  'Lauf',
  'Übung',
  'Pattern',
  'Groove',
  '10',
  '2',
  'a',
  'Ä',
];

String randomText(Random r) =>
    [for (var i = 0, n = 1 + r.nextInt(3); i < n; i++) pick(r, words)]
        .join(' ');

/// A library in memory; [sources] are the import sources (generated bytes).
class TestLibrary {
  TestLibrary(this.random, [MemoryFileStore? store])
    : store = store ?? MemoryFileStore();

  final Random random;
  final MemoryFileStore store;
  final sources = <String, Uint8List>{};
  var clock = DateTime.utc(2026, 11, 1);

  late Library library = open();

  Library open() => Library(
    store,
    probe: (_) => 1 + random.nextInt(600) / 2,
    readSource: (s) async => sources[s],
    now: () => clock,
    saveDelay: Duration.zero,
    random: Random(random.nextInt(1 << 31)),
  );

  /// Imports [n] new files with distinct contents.
  Future<void> importSome(int n, {String? folderId}) async {
    final names = <String>[];
    for (var i = 0; i < n; i++) {
      final name = 'f${sources.length}_${random.nextInt(1 << 30)}.mp3';
      sources[name] = Uint8List.fromList(utf8.encode('audio $name'));
      names.add(name);
    }
    clock = clock.add(Duration(seconds: 1 + random.nextInt(100)));
    await library.importFiles(names, folderId: folderId);
  }
}

PlaybackSettings randomSettings(Random r) => PlaybackSettings(
  speedEnabled: r.nextBool(),
  speed: 0.1 + r.nextInt(39) * 0.05,
  loopEnabled: r.nextBool(),
  loopStart: r.nextInt(3000) / 10,
  loopEnd: r.nextBool() ? 0 : r.nextInt(3000) / 10,
).copyWith(rampEnabled: r.nextBool(), rampStart: r.nextInt(250));

/// One random operation on [t]; returns its name (for the failure message).
Future<String> randomOperation(TestLibrary t) async {
  final r = t.random;
  final lib = t.library;
  final ids = lib.tracks.map((x) => x.id).toList();
  final realFolders = lib.folders.map((f) => f.id).toList();
  final folders = [null, ...realFolders];
  String? anyId() => ids.isEmpty ? null : pick(r, ids);
  switch (r.nextInt(13)) {
    case 0:
      await t.importSome(1 + r.nextInt(3), folderId: pick(r, folders));
      return 'import';
    case 1:
      lib.createFolder(r.nextInt(5) == 0 ? '  ' : randomText(r), fallback: 'F');
      return 'createFolder';
    case 2:
      if (realFolders.isNotEmpty) lib.deleteFolder(pick(r, realFolders));
      return 'deleteFolder';
    case 3:
      if (realFolders.isNotEmpty) {
        lib.renameFolder(pick(r, realFolders), randomText(r));
      }
      return 'renameFolder';
    case 4:
      final subset = {
        for (final id in ids)
          if (r.nextInt(3) == 0) id,
      };
      lib.moveTracks(
        subset,
        pick(r, folders),
        at: r.nextBool() ? null : r.nextInt(ids.length + 2) - 1,
      );
      return 'moveTracks';
    case 5:
      final id = anyId();
      if (id != null) {
        lib.placeTrack(
          id,
          pick(r, folders),
          beforeId: r.nextBool() ? null : anyId(),
        );
      }
      return 'placeTrack';
    case 6:
      lib.move(
        pick(r, folders),
        r.nextInt(ids.length + 2) - 1,
        r.nextInt(ids.length + 3) - 1,
      );
      return 'move';
    case 7:
      lib.sortOrder = pick(r, TrackSortOrder.values);
      return 'sortOrder';
    case 8:
      final id = anyId();
      if (id != null) {
        lib.editMetadata(
          id,
          title: r.nextInt(5) == 0 ? ' ' : randomText(r),
          artist: r.nextBool() ? null : randomText(r),
        );
      }
      return 'editMetadata';
    case 9:
      final id = anyId();
      if (id != null) lib.updateSettings(id, randomSettings(r));
      return 'updateSettings';
    case 10:
      if (ids.isNotEmpty && r.nextInt(3) == 0) lib.delete({anyId()!});
      return 'delete';
    case 11:
      return playlistStep(r, lib);
    default:
      lib.appearance = pick(r, Appearance.values);
      return 'appearance';
  }
}

/// #114: one random change to the playlists of [lib]; returns its name for the log.
String playlistStep(Random r, Library lib) {
  final ids = lib.tracks.map((t) => t.id).toList();
  final lists = lib.playlists;
  if (lists.isEmpty || r.nextInt(5) == 0) {
    lib.createPlaylist(randomText(r), fallback: 'P');
    return 'playlist create';
  }
  final p = pick(r, lists).id;
  final rows = lib.playlistTracks(p).length;
  switch (r.nextInt(7)) {
    case 0:
      lib.deletePlaylist(p);
      return 'playlist delete';
    case 1:
      lib.renamePlaylist(p, randomText(r));
      return 'playlist rename';
    case 2 || 3:
      if (ids.isEmpty) return 'playlist nothing to add';
      lib.addToPlaylist(p, [
        for (var i = r.nextInt(3); i >= 0; i--) pick(r, ids),
      ], at: r.nextBool() ? null : r.nextInt(rows + 1));
      return 'playlist add';
    case 4:
      lib.removeFromPlaylist(p, r.nextInt(rows + 1));
      return 'playlist remove';
    case 5:
      lib.movePlaylistEntry(p, r.nextInt(rows + 1), r.nextInt(rows + 1));
      return 'playlist move';
    default:
      final shared = !lib.playlist(p)!.shared;
      lib.setPlaylistShared(p, shared);
      return 'playlist ${shared ? 'share' : 'local'}';
  }
}

/// No track lost or duplicated, every track in exactly one existing folder (or none).
void checkTracks(Library lib, Set<String> expected, String after) {
  final ids = lib.tracks.map((t) => t.id).toList();
  expect(ids.toSet().length, ids.length, reason: 'duplicate after $after');
  expect(ids.toSet(), expected, reason: 'lost or extra track after $after');
  final sorted = lib.sortedTracks.map((t) => t.id).toList();
  expect(sorted.length, ids.length, reason: 'sorted list after $after');
  expect(sorted.toSet(), expected, reason: 'sorted list after $after');
  final folderIds = lib.folders.map((f) => f.id).toSet();
  final perFolder = [
    for (final f in [null, ...folderIds]) ...lib.sortedTracksIn(f),
  ].map((t) => t.id).toList();
  expect(perFolder.length, ids.length, reason: 'folders after $after');
  expect(perFolder.toSet(), expected, reason: 'folders after $after');
  // #114/AK7: playlists list only tracks of the library
  for (final p in lib.playlists) {
    expect(
      expected.containsAll(lib.playlistTracks(p.id).map((t) => t.id)),
      isTrue,
      reason: 'playlist with a missing track after $after',
    );
  }
  for (final t in lib.tracks) {
    expect(
      t.folderId == null || folderIds.contains(t.folderId),
      isTrue,
      reason: 'track in a missing folder after $after',
    );
  }
}

/// Everything the library shows, for comparing two libraries.
Map<String, Object?> snapshot(Library lib) => {
  'tracks': {for (final t in lib.tracks) t.id: t.toShared()},
  'folders': {
    for (final f in lib.folders) f.id: {'name': f.name, 'sync': f.sync},
  },
  'sortOrder': lib.sortOrder.name,
  'appearance': lib.appearance.name,
  'order': lib.sortedTracks.map((t) => t.id).toList(),
  'playlists': {
    for (final p in lib.playlists)
      p.id: {
        'name': p.name,
        'shared': p.shared,
        'rows': [for (final t in lib.playlistTracks(p.id)) t.id],
      },
  },
};

void main() {
  group('#10/AK1 library', () {
    property(
      'sorting and moving into folders neither lose nor duplicate a track',
      (r) async {
        final t = TestLibrary(r);
        await t.library.load();
        await t.importSome(r.nextInt(8));
        for (var i = 0, n = r.nextInt(4); i < n; i++) {
          t.library.createFolder(randomText(r));
        }
        var expected = t.library.tracks.map((x) => x.id).toSet();
        for (var i = 0, n = 5 + r.nextInt(30); i < n; i++) {
          final before = t.library.tracks.map((x) => x.id).toSet();
          final op = await randomOperation(t);
          final after = t.library.tracks.map((x) => x.id).toSet();
          if (op == 'import') {
            expect(after.containsAll(before), isTrue, reason: 'import lost');
            expected = after;
          } else if (op == 'delete') {
            expect(before.difference(after).length, lessThanOrEqualTo(1));
            expected = after;
          }
          checkTracks(t.library, expected, '$op (step $i)');
        }
      },
    );

    property('saving and loading gives the same state', (r) async {
      final t = TestLibrary(r);
      await t.library.load();
      await t.importSome(r.nextInt(8));
      for (var i = 0, n = r.nextInt(25); i < n; i++) {
        await randomOperation(t);
      }
      final before = snapshot(t.library);
      await t.library.save();
      final reloaded = t.open();
      await reloaded.load();
      expect(reloaded.lastError, isNull);
      expect(reloaded.droppedMissing, 0);
      expect(snapshot(reloaded), before);
      // A second save of the loaded library writes the same file.
      final bytes = t.store.files[Library.indexName]!;
      await reloaded.save();
      expect(
        utf8.decode(t.store.files[Library.indexName]!),
        utf8.decode(bytes),
      );
    });
  });

  group('#10/AK2 property helper', () {
    test('regressions run first, then the random cases with printed seed', () {
      final seeds = plannedSeeds(
        'x',
        const PropertyConfig(3, 7),
        regressions: [42, 43],
      );
      expect(seeds.map((s) => s.$2), [
        'regression',
        'regression',
        'case 0',
        'case 1',
        'case 2',
      ]);
      expect(seeds.take(2).map((s) => s.$1), [42, 43]);
      expect(seeds[2].$1, caseSeed(7, 0));
      // repeatable: the same run seed gives the same cases
      expect(
        plannedSeeds('x', const PropertyConfig(3, 7), regressions: []),
        plannedSeeds('x', const PropertyConfig(3, 7), regressions: []),
      );
      expect(caseSeed(7, 0), isNot(caseSeed(8, 0)));
    });

    test('number of cases and seed come from the environment', () {
      final c = PropertyConfig.fromEnvironment({
        'WP_PROPERTY_CASES': '5000',
        'WP_PROPERTY_SEED': '99',
      });
      expect((c.cases, c.seed), (5000, 99));
      final d = PropertyConfig.fromEnvironment({'WP_PROPERTY_CASES': 'x'});
      expect((d.cases, d.seed), (defaultCases, defaultSeed));
    });

    test('regressions.json: every entry names an existing property', () {
      final names = {
        'sorting and moving into folders neither lose nor duplicate a track',
        'saving and loading gives the same state',
        'loop bounds are valid after every change',
        'parse(format(x)) == x for times',
        'random edits, deletions and syncs on 2 to 4 devices converge',
        'damaged state.json never crashes and never loses local data',
        'damaged library.json never crashes and is reported',
        'migration twice changes nothing and reports nothing',
      };
      for (final name in names) {
        regressionSeeds(name); // readable
      }
      expect(
        names.containsAll(
          (jsonDecode(
            File('test/property/regressions.json').readAsStringSync(),
          ) as Map).keys.where((k) => !(k as String).startsWith('_')),
        ),
        isTrue,
      );
    });
  });
}
